import express from 'express';
import cors from 'cors';
import mysql from 'mysql2/promise';
import http from 'node:http';
import crypto from 'node:crypto';
import {WebSocketServer,WebSocket} from 'ws';
import {createNestApplication} from './nest/platform.js';
import {initializeStorage,ensureStorageFolders,putReport,copyImage,storagePrefix,storageProvider} from './storage.js';
import {initializeRealtime,publishRealtime,realtimeStatus,closeRealtime} from './realtime.js';

const app=express(),port=Number(process.env.PORT||5000),masterDb=process.env.MASTER_DB_NAME||'knockout_master';
const server=http.createServer(app),socketServer=new WebSocketServer({server,path:'/ws'});
const rootConfig={host:process.env.DB_HOST||'mariadb',port:Number(process.env.DB_PORT||3306),user:process.env.DB_ROOT_USER||'root',password:process.env.DB_ROOT_PASSWORD||'knockout_root',enableKeepAlive:true,keepAliveInitialDelay:10000,connectTimeout:Number(process.env.DB_CONNECT_TIMEOUT_MS||10000)};
const sessionSecret=process.env.MASTER_SESSION_SECRET||`${rootConfig.password}:${masterDb}:knockout-session`;
let adminPool,masterPool;
app.use(cors());app.use(express.json({limit:'6mb'}));
const asyncRoute=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const ident=value=>{const clean=String(value||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');if(!/^[a-z][a-z0-9_]{1,54}$/.test(clean))throw Object.assign(new Error('Hotel name cannot be converted to a valid database name'),{status:400});return clean};
const tenantDatabaseName=value=>`tenant_${ident(value)}`;
const validTenant=value=>/^(?:knockout(?:_[0-9]+)?|tenant_[a-z][a-z0-9_]{1,54})$/.test(String(value||''));
const defaultModules={tables:true,bookings:true,billing:true,parcels:true,menu:true,stock:true,finance:true,staff:true,kitchen:true,juicer:true};
const moduleCatalog={tables:['Tables & Waiters',499],bookings:['Table Bookings',299],billing:['Orders & Billing',699],parcels:['Parcel Orders',399],menu:['Food & Photos',299],stock:['Stock Management',499],finance:['Finance Management',599],staff:['Staff Management',399],kitchen:['Chef Portal',499],juicer:['Juicer Portal',299]};
const packages={starter:['tables','billing','menu','kitchen'],growth:['tables','bookings','billing','parcels','menu','stock','kitchen'],complete:Object.keys(defaultModules)};
const parseModules=value=>{try{return{...defaultModules,...(typeof value==='string'?JSON.parse(value):value||{})}}catch{return{...defaultModules}}};
const randomDigits=length=>Array.from({length},()=>crypto.randomInt(0,10)).join('');
async function generateHotelId(){for(let attempt=0;attempt<200;attempt++){const hotelId=String(crypto.randomInt(1000,10000)),[[used]]=await masterPool.query('SELECT id FROM companies WHERE hotel_id=? LIMIT 1',[hotelId]);if(!used)return hotelId}throw Object.assign(new Error('Unable to allocate a Hotel ID. Please try again.'),{status:503})}
async function generateTenantPin(databaseName){for(let attempt=0;attempt<200;attempt++){const pin=String(crypto.randomInt(100000,1000000)),[[used]]=await adminPool.query(`SELECT id FROM \`${databaseName}\`.users WHERE pin=? AND deleted_at IS NULL LIMIT 1`,[pin]);if(!used)return pin}throw Object.assign(new Error('Unable to allocate an Admin PIN. Please try again.'),{status:503})}
const socketDatabase=value=>validTenant(value)?String(value):value==='master'?'master':null;
const encode=value=>Buffer.from(JSON.stringify(value)).toString('base64url');
function issuePortalToken(user){const payload=encode({id:user.id,role:user.role,companyDatabase:user.companyDatabase,exp:Date.now()+12*60*60*1000}),signature=crypto.createHmac('sha256',sessionSecret).update(payload).digest('base64url');return `${payload}.${signature}`}
function verifyPortalToken(value){try{const[payload,signature]=String(value||'').replace(/^Bearer\s+/i,'').split('.'),expected=crypto.createHmac('sha256',sessionSecret).update(payload).digest('base64url');if(!signature||signature.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(signature),Buffer.from(expected)))return null;const data=JSON.parse(Buffer.from(payload,'base64url')),validRole=['admin','waiter','chef','juicer','superadmin'].includes(data.role),validCompany=data.role==='superadmin'||validTenant(data.companyDatabase);return data.exp>Date.now()&&validRole&&validCompany?data:null}catch{return null}}
function broadcastChange(database,resource='state',details={}){
 const event={type:'state.changed',database,resource,...details,at:new Date().toISOString()},message=JSON.stringify(event);
 for(const client of socketServer.clients)if(client.readyState===WebSocket.OPEN&&(client.database===database||client.database==='master'))client.send(message);
 publishRealtime(event);
}
function relayChange(event){
 const message=JSON.stringify(event);
 for(const client of socketServer.clients)if(client.readyState===WebSocket.OPEN&&(client.database===event.database||client.database==='master'))client.send(message);
}
socketServer.on('connection',(socket,request)=>{
 const params=new URL(request.url,'http://localhost').searchParams,database=socketDatabase(params.get('database')),session=verifyPortalToken(params.get('token'));
 const authorized=database==='master'?session?.role==='superadmin':session?.companyDatabase===database&&['admin','waiter','chef','juicer'].includes(session?.role);
 if(!database||!authorized)return socket.close(1008,'Unauthorized live tracking channel');
 socket.database=database;socket.isAlive=true;
 socket.on('pong',()=>{socket.isAlive=true});
 socket.send(JSON.stringify({type:'connected',database,at:new Date().toISOString()}));
});
const socketHeartbeat=setInterval(()=>{for(const socket of socketServer.clients){if(socket.isAlive===false){socket.terminate();continue}socket.isAlive=false;socket.ping()}},25000);
socketServer.on('close',()=>clearInterval(socketHeartbeat));
app.use((req,res,next)=>{
 if(['GET','HEAD','OPTIONS'].includes(req.method)||['/api/login','/api/public/resolve-login'].includes(req.path))return next();
 res.on('finish',()=>{if(res.statusCode<400){const requested=String(req.headers['x-company-database']||'');const database=socketDatabase(requested)||'master';broadcastChange(database,req.path)}});
 next();
});

async function activeCompanies(includeSuspended=false){
 const[rows]=await masterPool.query(`SELECT id,company_name companyName,database_name databaseName FROM companies ${includeSuspended?'':"WHERE status='active'"} ORDER BY id`);
 return rows.filter(company=>validTenant(company.databaseName));
}

async function findPortalLogins(role,pin,includeInactive=false,hotelId=null){
 const matches=[];
 if(!role||role==='superadmin'){
  const[[masterUser]]=await masterPool.query(`SELECT id,name FROM master_users WHERE pin=? ${includeInactive?'':'AND active=TRUE'} LIMIT 1`,[String(pin)]);
  if(masterUser)matches.push({...masterUser,role:'superadmin',companyDatabase:null,companyName:'KnockOUT Master'});
 }
 const params=role?[role,String(pin)]:[String(pin)];
 if(hotelId)params.push(String(hotelId));
 const[users]=await masterPool.query(`SELECT cu.tenant_user_id id,cu.name,cu.role,cu.active userActive,c.database_name companyDatabase,c.company_name companyName,c.hotel_id hotelId,c.modules,c.status companyStatus FROM company_users cu JOIN companies c ON c.id=cu.company_id WHERE ${role?'cu.role=? AND ':''}cu.pin=? ${hotelId?'AND c.hotel_id=? ':''}${includeInactive?'':"AND cu.active=TRUE AND c.status='active'"}`,params);
 users.forEach(user=>{user.modules=parseModules(user.modules)});
 matches.push(...users);
 return matches;
}

async function syncCompanyUsers(databaseName){
 if(!validTenant(databaseName))return;
 const[[company]]=await masterPool.query('SELECT id FROM companies WHERE database_name=?',[databaseName]);
 if(!company)return;
 const[users]=await adminPool.query(`SELECT id,name,role,pin,phone,email,profile_image_url profileImageUrl,active FROM \`${databaseName}\`.users WHERE deleted_at IS NULL`);
 const conn=await masterPool.getConnection();
 try{await conn.beginTransaction();await conn.query('DELETE FROM company_users WHERE company_id=?',[company.id]);for(const user of users)await conn.query('INSERT INTO company_users (company_id,tenant_user_id,name,role,pin,phone,email,profile_image_url,active) VALUES (?,?,?,?,?,?,?,?,?)',[company.id,user.id,user.name,user.role,user.pin,user.phone||'',user.email||'',user.profileImageUrl||null,!!user.active]);await conn.commit()}catch(error){await conn.rollback();throw error}finally{conn.release()}
}

async function initialize(){
 adminPool=mysql.createPool({...rootConfig,waitForConnections:true,connectionLimit:Number(process.env.MASTER_ADMIN_POOL_SIZE||20),maxIdle:Number(process.env.DB_POOL_MAX_IDLE||10),idleTimeout:Number(process.env.DB_POOL_IDLE_TIMEOUT_MS||60000),queueLimit:Number(process.env.DB_QUEUE_LIMIT||500)});
 await adminPool.query(`CREATE DATABASE IF NOT EXISTS \`${masterDb}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
 masterPool=mysql.createPool({...rootConfig,database:masterDb,waitForConnections:true,connectionLimit:Number(process.env.MASTER_DB_POOL_SIZE||30),maxIdle:Number(process.env.DB_POOL_MAX_IDLE||15),idleTimeout:Number(process.env.DB_POOL_IDLE_TIMEOUT_MS||60000),queueLimit:Number(process.env.DB_QUEUE_LIMIT||500)});
 await masterPool.query(`CREATE TABLE IF NOT EXISTS master_users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,pin VARCHAR(20) NOT NULL,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS companies (id INT AUTO_INCREMENT PRIMARY KEY,company_name VARCHAR(160) NOT NULL UNIQUE,database_name VARCHAR(64) NOT NULL UNIQUE,cy_db VARCHAR(64) NULL UNIQUE,hotel_id CHAR(4) NULL UNIQUE,modules JSON NULL,admin_name VARCHAR(120) NOT NULL,email VARCHAR(160) DEFAULT '',phone VARCHAR(30) DEFAULT '',status ENUM('active','suspended') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS company_users (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,tenant_user_id INT NOT NULL,name VARCHAR(120) NOT NULL,role ENUM('admin','waiter','chef','juicer') NOT NULL,pin VARCHAR(80) NOT NULL,phone VARCHAR(30) DEFAULT '',email VARCHAR(160) DEFAULT '',profile_image_url VARCHAR(500) NULL,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY company_tenant_user (company_id,tenant_user_id),UNIQUE KEY company_pin (company_id,pin),FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE)`);
 for(const statement of ["ALTER TABLE company_users ADD COLUMN email VARCHAR(160) DEFAULT '' AFTER phone","ALTER TABLE company_users ADD COLUMN profile_image_url VARCHAR(500) NULL AFTER email"]){try{await masterPool.query(statement)}catch(error){if(error.code!=='ER_DUP_FIELDNAME')throw error}}
 for(const statement of ["ALTER TABLE companies ADD COLUMN hotel_id CHAR(4) NULL UNIQUE AFTER database_name","ALTER TABLE companies ADD COLUMN modules JSON NULL AFTER hotel_id","ALTER TABLE company_users DROP INDEX global_company_pin","ALTER TABLE company_users ADD UNIQUE KEY company_pin (company_id,pin)"]){try{await masterPool.query(statement)}catch(error){if(!['ER_DUP_FIELDNAME','ER_CANT_DROP_FIELD_OR_KEY','ER_DUP_KEYNAME'].includes(error.code))throw error}}
 try{await masterPool.query('ALTER TABLE companies ADD COLUMN cy_db VARCHAR(64) NULL UNIQUE AFTER database_name')}catch(error){if(!['ER_DUP_FIELDNAME','ER_DUP_KEYNAME'].includes(error.code))throw error}
 await masterPool.query('UPDATE companies SET cy_db=database_name WHERE cy_db IS NULL');
 await masterPool.query(`CREATE TABLE IF NOT EXISTS company_registration_requests (id INT AUTO_INCREMENT PRIMARY KEY,company_name VARCHAR(160) NOT NULL,hotel_id CHAR(4) NULL,admin_name VARCHAR(120) NOT NULL,admin_pin VARCHAR(20) NULL,email VARCHAR(160) NOT NULL,phone VARCHAR(30) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',review_note VARCHAR(255) DEFAULT '',company_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,INDEX registration_status (status,created_at),FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS saas_invoices (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,billing_month DATE NOT NULL,line_items JSON NOT NULL,subtotal DECIMAL(12,2) NOT NULL,tax_rate DECIMAL(5,2) NOT NULL DEFAULT 18,tax DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,status ENUM('due','paid') NOT NULL DEFAULT 'due',paid_at DATETIME NULL,generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY company_billing_month(company_id,billing_month),INDEX invoice_month(billing_month,status),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS notification_outbox (id INT AUTO_INCREMENT PRIMARY KEY,recipient VARCHAR(180) NOT NULL,channel ENUM('email','sms') NOT NULL,subject VARCHAR(180) DEFAULT '',message TEXT NOT NULL,status ENUM('queued','sent','failed') DEFAULT 'queued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS tenant_subscriptions (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,package_code VARCHAR(30) NOT NULL,period_months INT NOT NULL,started_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,grace_ends_at DATETIME NOT NULL,status ENUM('active','grace','expired') DEFAULT 'active',last_reminder_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS usage_logins (id BIGINT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,user_id INT NOT NULL,role VARCHAR(30) NOT NULL,logged_in_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX company_login(company_id,logged_in_at),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE)`);
 await masterPool.query(`CREATE TABLE IF NOT EXISTS module_pricing (module_key VARCHAR(30) PRIMARY KEY,module_name VARCHAR(100) NOT NULL,monthly_price DECIMAL(12,2) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)`);
 for(const[key,[name,price]]of Object.entries(moduleCatalog))await masterPool.query('INSERT IGNORE INTO module_pricing (module_key,module_name,monthly_price) VALUES (?,?,?)',[key,name,price]);
 try{await masterPool.query('ALTER TABLE company_registration_requests ADD COLUMN hotel_id CHAR(4) NULL AFTER company_name')}catch(error){if(error.code!=='ER_DUP_FIELDNAME')throw error}
 await masterPool.query('ALTER TABLE company_registration_requests MODIFY admin_pin VARCHAR(20) NULL');
 for(const statement of ["ALTER TABLE company_registration_requests ADD COLUMN temporary_pin CHAR(6) NULL UNIQUE AFTER admin_pin","ALTER TABLE company_registration_requests ADD COLUMN package_code VARCHAR(30) NOT NULL DEFAULT 'starter' AFTER temporary_pin","ALTER TABLE company_registration_requests ADD COLUMN period_months INT NOT NULL DEFAULT 1 AFTER package_code","ALTER TABLE company_registration_requests ADD COLUMN selected_modules JSON NULL AFTER period_months","ALTER TABLE company_registration_requests ADD COLUMN setup_data JSON NULL AFTER selected_modules","ALTER TABLE company_registration_requests ADD COLUMN payment_reference VARCHAR(120) NULL AFTER setup_data","ALTER TABLE company_registration_requests ADD COLUMN completed_at DATETIME NULL AFTER reviewed_at"]){try{await masterPool.query(statement)}catch(error){if(!['ER_DUP_FIELDNAME','ER_DUP_KEYNAME'].includes(error.code))throw error}}
 await masterPool.query("CREATE OR REPLACE VIEW tenant_waiting_list AS SELECT * FROM company_registration_requests WHERE completed_at IS NULL");
 await masterPool.query("CREATE OR REPLACE VIEW tenant_registrations AS SELECT * FROM company_registration_requests WHERE completed_at IS NOT NULL");
 await adminPool.query(`GRANT SELECT ON \`${masterDb}\`.master_users TO 'knockout'@'%'`);
 await adminPool.query('FLUSH PRIVILEGES');
 const[[masterCount]]=await masterPool.query('SELECT COUNT(*) count FROM master_users');
 if(!masterCount.count)await masterPool.query("INSERT INTO master_users (name,pin) VALUES ('KnockOUT Master','9999')");
 await masterPool.query("INSERT IGNORE INTO companies (company_name,database_name,cy_db,admin_name,email,status) VALUES ('KnockOUT 1','knockout','knockout','Arjun Kumar','admin@knockout1.local','active')");
 await masterPool.query("UPDATE companies SET hotel_id=CASE WHEN database_name='knockout' THEN '1234' ELSE LPAD(2000+id,4,'0') END WHERE hotel_id IS NULL");
 await masterPool.query('UPDATE companies SET modules=? WHERE modules IS NULL',[JSON.stringify(defaultModules)]);
 const[companies]=await masterPool.query('SELECT database_name databaseName FROM companies');
 for(const company of companies){await ensureDailyFinanceTables(company.databaseName);await syncCompanyUsers(company.databaseName)}
 await initializeStorage();
 const[storageCompanies]=await masterPool.query('SELECT company_name companyName,database_name databaseName FROM companies');
 for(const company of storageCompanies){await ensureStorageFolders(company.companyName);await migrateTenantImages(company)}
 await generateMonthlySaasInvoices();
}

async function generateMonthlySaasInvoices(){
 const billingMonth=new Date().toISOString().slice(0,7)+'-01',[companies]=await masterPool.query("SELECT c.id,c.modules FROM companies c WHERE NOT EXISTS (SELECT 1 FROM tenant_subscriptions s WHERE s.company_id=c.id AND s.status IN ('active','grace') AND NOW()<s.grace_ends_at)"),[pricingRows]=await masterPool.query('SELECT module_key moduleKey,module_name moduleName,monthly_price monthlyPrice FROM module_pricing'),pricing=Object.fromEntries(pricingRows.map(row=>[row.moduleKey,[row.moduleName,Number(row.monthlyPrice)]]));
 for(const company of companies){const modules=parseModules(company.modules),items=Object.entries(pricing).filter(([key])=>modules[key]!==false).map(([key,[name,price]])=>({key,name,price})),subtotal=items.reduce((sum,item)=>sum+item.price,0),tax=Number((subtotal*.18).toFixed(2));await masterPool.query('INSERT INTO saas_invoices (company_id,billing_month,line_items,subtotal,tax_rate,tax,total) VALUES (?,?,?, ?,18,?,?) ON DUPLICATE KEY UPDATE line_items=IF(status="due",VALUES(line_items),line_items),subtotal=IF(status="due",VALUES(subtotal),subtotal),tax=IF(status="due",VALUES(tax),tax),total=IF(status="due",VALUES(total),total)',[company.id,billingMonth,JSON.stringify(items),subtotal,tax,subtotal+tax])}
}

async function queueNotice(recipient,channel,subject,message){await masterPool.query('INSERT INTO notification_outbox (recipient,channel,subject,message) VALUES (?,?,?,?)',[recipient,channel,subject,message]);const url=process.env.NOTIFICATION_WEBHOOK_URL;if(url)fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({recipient,channel,subject,message})}).catch(()=>{})}
async function currentPricing(){const[rows]=await masterPool.query('SELECT module_key moduleKey,module_name moduleName,monthly_price monthlyPrice FROM module_pricing ORDER BY module_name');return Object.fromEntries(rows.map(row=>[row.moduleKey,{name:row.moduleName,price:Number(row.monthlyPrice)}]))}
async function generateTemporaryPin(){for(let i=0;i<200;i++){const pin=randomDigits(6),[[used]]=await masterPool.query('SELECT id FROM company_registration_requests WHERE temporary_pin=? AND completed_at IS NULL',[pin]);if(!used)return pin}throw Object.assign(new Error('Unable to generate temporary access PIN'),{status:503})}
async function enforceSubscriptions(){const[expired]=await masterPool.query("SELECT s.id,s.company_id companyId,c.company_name companyName,c.email,c.phone FROM tenant_subscriptions s JOIN companies c ON c.id=s.company_id WHERE s.status<>'expired' AND NOW()>s.grace_ends_at");for(const row of expired){await masterPool.query("UPDATE tenant_subscriptions SET status='expired' WHERE id=?",[row.id]);await masterPool.query("UPDATE companies SET status='suspended' WHERE id=?",[row.companyId]);await queueNotice(row.email,'email','KnockOUT subscription suspended',`${row.companyName} was suspended because renewal payment was not received during the two-day grace period.`)}const[grace]=await masterPool.query("SELECT s.id,s.company_id companyId,c.company_name companyName,c.email,c.phone,s.expires_at expiresAt FROM tenant_subscriptions s JOIN companies c ON c.id=s.company_id WHERE s.status='active' AND NOW()>s.expires_at AND NOW()<=s.grace_ends_at");for(const row of grace){await masterPool.query("UPDATE tenant_subscriptions SET status='grace',last_reminder_at=NOW() WHERE id=?",[row.id]);await queueNotice(row.email,'email','KnockOUT renewal payment due',`${row.companyName} subscription has expired. Please renew within two days to avoid suspension.`);if(row.phone)await queueNotice(row.phone,'sms','Renewal due',`KnockOUT subscription expired. Renew within 2 days to keep ${row.companyName} active.`)}}

async function ensureDailyFinanceTables(databaseName){
 if(!validTenant(databaseName))return;
 await adminPool.query(`CREATE TABLE IF NOT EXISTS \`${databaseName}\`.supplier_purchases (id INT AUTO_INCREMENT PRIMARY KEY, supplier_name VARCHAR(160) NOT NULL, invoice_number VARCHAR(100) DEFAULT '', description VARCHAR(255) NOT NULL, purchase_date DATE NOT NULL, total_amount DECIMAL(12,2) NOT NULL, notes VARCHAR(255) DEFAULT '', created_by VARCHAR(120) DEFAULT 'Admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)`);
 await adminPool.query(`CREATE TABLE IF NOT EXISTS \`${databaseName}\`.supplier_payments (id INT AUTO_INCREMENT PRIMARY KEY, purchase_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_method VARCHAR(40) DEFAULT 'Cash', payment_date DATE NOT NULL, reference VARCHAR(100) DEFAULT '', notes VARCHAR(255) DEFAULT '', created_by VARCHAR(120) DEFAULT 'Admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (purchase_id))`);
 await adminPool.query(`CREATE TABLE IF NOT EXISTS \`${databaseName}\`.kitchen_staff (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, designation VARCHAR(100) NOT NULL DEFAULT 'Chef', phone VARCHAR(30) DEFAULT '', specialization VARCHAR(120) DEFAULT '', pay_type ENUM('daily','monthly') DEFAULT 'monthly', pay_rate DECIMAL(10,2) DEFAULT 0, joined_on DATE NULL, notes VARCHAR(255) DEFAULT '', active BOOLEAN DEFAULT TRUE, created_by VARCHAR(120) DEFAULT 'Head Chef', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)`);
 await adminPool.query(`ALTER TABLE \`${databaseName}\`.users MODIFY pay_type ENUM('daily','monthly','hourly') DEFAULT 'monthly'`);
 await adminPool.query(`UPDATE \`${databaseName}\`.users SET pay_type='daily' WHERE pay_type='hourly'`);
 await adminPool.query(`ALTER TABLE \`${databaseName}\`.users MODIFY pay_type ENUM('daily','monthly') DEFAULT 'monthly'`);
 await adminPool.query(`ALTER TABLE \`${databaseName}\`.kitchen_staff MODIFY pay_type ENUM('daily','monthly','hourly') DEFAULT 'monthly'`);
 await adminPool.query(`UPDATE \`${databaseName}\`.kitchen_staff SET pay_type='daily' WHERE pay_type='hourly'`);
 await adminPool.query(`ALTER TABLE \`${databaseName}\`.kitchen_staff MODIFY pay_type ENUM('daily','monthly') DEFAULT 'monthly'`);
}

async function migrateTenantImages(company){
 const prefix=`${storagePrefix(company.companyName)}/images/`;
 const[menu]=await adminPool.query(`SELECT id,image_object imageObject FROM \`${company.databaseName}\`.menu_items WHERE image_object IS NOT NULL AND image_object<>''`);
 for(const item of menu){if(item.imageObject.startsWith(prefix))continue;try{const stored=await copyImage(company.companyName,item.imageObject,`menu/${item.id}-${String(item.imageObject).split('/').pop()}`);await adminPool.query(`UPDATE \`${company.databaseName}\`.menu_items SET image_object=?,image_url=? WHERE id=?`,[stored.objectName,stored.url,item.id])}catch{}}
 const[users]=await adminPool.query(`SELECT id,profile_image_object imageObject FROM \`${company.databaseName}\`.users WHERE profile_image_object IS NOT NULL AND profile_image_object<>''`);
 for(const user of users){if(user.imageObject.startsWith(prefix))continue;try{const stored=await copyImage(company.companyName,user.imageObject,`profiles/${user.id}-${String(user.imageObject).split('/').pop()}`);await adminPool.query(`UPDATE \`${company.databaseName}\`.users SET profile_image_object=?,profile_image_url=? WHERE id=?`,[stored.objectName,stored.url,user.id])}catch{}}
}

async function provisionCompany({companyName,adminName,email='',phone='',selectedModules=null}){
 const databaseName=tenantDatabaseName(companyName);
 if(!adminName)throw Object.assign(new Error('Admin name is required'),{status:400});
 const[[exists]]=await masterPool.query('SELECT id FROM companies WHERE company_name=? OR database_name=?',[companyName,databaseName]);
 if(exists)throw Object.assign(new Error('This company or database is already registered'),{status:409});
 const[[dbExists]]=await adminPool.query('SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=?',[databaseName]);
 if(dbExists)throw Object.assign(new Error(`Database ${databaseName} already exists`),{status:409});
 const hotelId=await generateHotelId();
 try{
  await adminPool.query(`CREATE DATABASE \`${databaseName}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
  const[tables]=await adminPool.query("SELECT TABLE_NAME tableName FROM information_schema.TABLES WHERE TABLE_SCHEMA='knockout' AND TABLE_TYPE='BASE TABLE'");
  for(const {tableName} of tables)await adminPool.query(`CREATE TABLE \`${databaseName}\`.\`${tableName}\` LIKE \`knockout\`.\`${tableName}\``);
  await adminPool.query(`INSERT INTO \`${databaseName}\`.settings (id,hotel_name,tax_rate,cgst_rate,service_charge,currency) VALUES (1,?,2.5,2.5,18,'INR')`,[companyName]);
  const adminPin=await generateTenantPin(databaseName);
  await adminPool.query(`INSERT INTO \`${databaseName}\`.users (name,role,pin,phone,active) VALUES (?,'admin',?,?,TRUE)`,[adminName,adminPin,phone]);
  await adminPool.query(`INSERT INTO \`${databaseName}\`.menu_items (id,name,category,description,price,icon,image_url,image_object,is_combo,available) SELECT id,name,category,description,price,icon,image_url,image_object,is_combo,available FROM knockout.menu_items WHERE available=TRUE`);
  await adminPool.query(`INSERT INTO \`${databaseName}\`.combo_components (combo_id,menu_id,quantity) SELECT combo_id,menu_id,quantity FROM knockout.combo_components`);
  await adminPool.query(`INSERT INTO \`${databaseName}\`.inventory (name,category,quantity,unit,min_quantity,cost) SELECT name,category,0,unit,min_quantity,cost FROM knockout.inventory`);
  await adminPool.query(`GRANT ALL PRIVILEGES ON \`${databaseName}\`.* TO 'knockout'@'%'`);
  await adminPool.query('FLUSH PRIVILEGES');
  const enabledModules=selectedModules?Object.fromEntries(Object.keys(defaultModules).map(key=>[key,selectedModules.includes(key)])):defaultModules;
  await ensureStorageFolders(companyName);
  const[result]=await masterPool.query('INSERT INTO companies (company_name,database_name,cy_db,hotel_id,modules,admin_name,email,phone) VALUES (?,?,?,?,?,?,?,?)',[companyName,databaseName,databaseName,String(hotelId),JSON.stringify(enabledModules),adminName,email,phone]);
  await syncCompanyUsers(databaseName);
  return{id:result.insertId,companyName,databaseName,hotelId:String(hotelId),adminPin,modules:enabledModules,adminName,email,phone,status:'active'};
 }catch(error){await adminPool.query(`DROP DATABASE IF EXISTS \`${databaseName}\``).catch(()=>{});throw error}
}

async function companySummary(company){
 company.modules=parseModules(company.modules);
 try{if(!validTenant(company.databaseName))throw new Error('Invalid tenant database');const db=`\`${company.databaseName}\``;const[[users],[orders],[revenue],[stock],[daily]]=await Promise.all([masterPool.query('SELECT tenant_user_id id,name,role,pin,phone,active FROM company_users WHERE company_id=? ORDER BY role,name',[company.id]),adminPool.query(`SELECT COUNT(*) count FROM ${db}.orders WHERE status<>'completed'`),adminPool.query(`SELECT COALESCE(SUM(total),0) total FROM ${db}.orders WHERE payment_status='paid'`),adminPool.query(`SELECT COUNT(*) count FROM ${db}.inventory WHERE quantity<=min_quantity`),adminPool.query(`SELECT DATE_FORMAT(completed_at,'%Y-%m-%d') day,COUNT(*) bills,COALESCE(SUM(total),0) total FROM ${db}.orders WHERE payment_status='paid' AND completed_at IS NOT NULL GROUP BY DATE(completed_at) ORDER BY day DESC LIMIT 31`)]);return{...company,users:users.map(user=>({...user,active:!!user.active})),staffCount:users.filter(user=>user.active).length,adminLoginActive:users.some(user=>user.role==='admin'&&user.active),activeOrders:orders[0].count,revenue:Number(revenue[0].total),dailyRevenue:daily.map(row=>({date:row.day,bills:row.bills,total:Number(row.total)})),lowStock:stock[0].count,online:true}}catch{return{...company,users:[],staffCount:0,adminLoginActive:false,activeOrders:0,revenue:0,dailyRevenue:[],lowStock:0,online:false}}
}

